// src/components/AboutPage.js

import React from 'react';

function AboutPage() {
  return (
    <main style={{ padding: '80px 0 0', minHeight: '100vh', backgroundColor: '#f0f2f5', color: '#333' }}>
      <section className="hero-section section-common" style={{ padding: '80px 20px', textAlign: 'center' }}>
        <h1 className="main-heading" style={{ fontSize: '36px', marginBottom: '10px' }}>Arch-GPT의 이야기</h1>
        <p className="sub-heading" style={{ fontSize: '18px', color: '#555', marginBottom: '40px' }}>AI와 건축 디자인의 만남, 경계를 허물다.</p>
        
        <div className="story-cards" style={{ display: 'flex', justifyContent: 'center', gap: '30px', maxWidth: '1000px', margin: '0 auto' }}>
          {/* 핵심 비전 카드 내용 */}
          <div className="story-card accent-card" style={{ flex: 1, padding: '30px', backgroundColor: '#fff', borderRadius: '10px', boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)' }}>
            <h3 style={{ color: '#2563eb', marginBottom: '15px' }}>혁신적인 기술</h3>
            <p>우리는 AI 기술을 통해 건축 디자인 과정을 혁신하고, 사용자에게 최적의 공간 솔루션을 제공합니다.</p>
          </div>
          <div className="story-card" style={{ flex: 1, padding: '30px', backgroundColor: '#fff', borderRadius: '10px', boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)' }}>
            <h3 style={{ color: '#2563eb', marginBottom: '15px' }}>사용자 접근성</h3>
            <p>모든 사용자가 쉽게 접근하고 사용할 수 있는 직관적인 디자인 도구를 제공합니다.</p>
          </div>
        </div>
      </section>

      <section className="section-common section-orange-bg" style={{ padding: '60px 20px', backgroundColor: '#f4f4f4', marginTop: '40px', textAlign: 'center' }}>
        <h2 className="main-heading" style={{ color: '#333', marginBottom: '20px' }}>TO. 우리의 사용자에게</h2>
        <p className="sub-heading" style={{ color: '#666' }}>Arch-GPT와 함께 만들어갈 당신만의 공간 스토리를 기대합니다!</p>
      </section>
    </main>
  );
}

export default AboutPage;
